+package org.apache.flink.runtime.scheduler.metrics;
+
+import org.apache.flink.api.common.JobID;
+import org.apache.flink.api.common.JobStatus;
+import org.apache.flink.configuration.ReporterOptions;
+import org.apache.flink.runtime.metrics.util.InterceptingOperatorReporterGroup;
+import org.apache.flink.util.clock.ManualClock;
+
+import org.junit.jupiter.api.Test;
+
+import java.time.Duration;
+import java.util.Map;
+
+import static org.apache.flink.runtime.scheduler.metrics.StateTimeReporterTest.enable;
+import static org.apache.flink.runtime.scheduler.metrics.StateTimeReporterTest.extractReporters;
+import static org.assertj.core.api.Assertions.assertThat;
+
+class JobStatusReportersTest {
+
+    @Test
+    void testStateReporter() {
+        final JobStatusMetrics jobStatusReporters =
+                new JobStatusMetrics(
+                        0L,
+                        enable(
+                                ReporterOptions.JobStatusMetrics.STATE,
+                                ReporterOptions.JobStatusMetrics.CURRENT_TIME,
+                                ReporterOptions.JobStatusMetrics.TOTAL_TIME));
+
+        final StateTimeReporter reporter = jobStatusReporters.createTimeMetric(JobStatus.RUNNING);
+
+        assertThat(reporter.getBinary()).isEqualTo(0L);
+        jobStatusReporters.jobStatusChanges(new JobID(), JobStatus.RUNNING, 1L);
+        assertThat(reporter.getBinary()).isEqualTo(1L);
+        jobStatusReporters.jobStatusChanges(new JobID(), JobStatus.RESTARTING, 2L);
+        assertThat(reporter.getBinary()).isEqualTo(0L);
+    }
+
+    @Test
+    void testCurrentTimeReporter() {
+        final ManualClock clock = new ManualClock();
+        final JobStatusMetrics jobStatusReporters =
+                new JobStatusMetrics(
+                        0L,
+                        enable(
+                                ReporterOptions.JobStatusMetrics.STATE,
+                                ReporterOptions.JobStatusMetrics.CURRENT_TIME,
+                                ReporterOptions.JobStatusMetrics.TOTAL_TIME),
+                        clock);
+        final StateTimeReporter reporter = jobStatusReporters.createTimeMetric(JobStatus.RUNNING);
+
+        assertThat(reporter.getCurrentTime()).isEqualTo(0L);
+        jobStatusReporters.jobStatusChanges(new JobID(), JobStatus.RUNNING, 1L);
+        clock.advanceTime(Duration.ofMillis(11));
+        assertThat(reporter.getCurrentTime()).isEqualTo(10L);
+        jobStatusReporters.jobStatusChanges(new JobID(), JobStatus.RESTARTING, 15L);
+        assertThat(reporter.getCurrentTime()).isEqualTo(0L);
+    }
+
+    @Test
+    void testTotalTimeReporter() {
+        final ManualClock clock = new ManualClock(0);
+        final JobStatusMetrics jobStatusReporters =
+                new JobStatusMetrics(
+                        0L,
+                        enable(
+                                ReporterOptions.JobStatusMetrics.STATE,
+                                ReporterOptions.JobStatusMetrics.CURRENT_TIME,
+                                ReporterOptions.JobStatusMetrics.TOTAL_TIME),
+                        clock);
+
+        final StateTimeReporter reporter = jobStatusReporters.createTimeMetric(JobStatus.RUNNING);
+
+        assertThat(reporter.getTotalTime()).isEqualTo(0L);
+
+        jobStatusReporters.jobStatusChanges(
+                new JobID(), JobStatus.RUNNING, clock.absoluteTimeMillis());
+
+        clock.advanceTime(Duration.ofMillis(10));
+        assertThat(reporter.getTotalTime()).isEqualTo(10L);
+
+        jobStatusReporters.jobStatusChanges(
+                new JobID(), JobStatus.RESTARTING, clock.absoluteTimeMillis());
+
+        clock.advanceTime(Duration.ofMillis(4));
+        assertThat(reporter.getTotalTime()).isEqualTo(10L);
+
+        jobStatusReporters.jobStatusChanges(
+                new JobID(), JobStatus.RUNNING, clock.absoluteTimeMillis());
+
+        clock.advanceTime(Duration.ofMillis(1));
+        assertThat(reporter.getTotalTime()).isEqualTo(11L);
+    }
+
+    @Test
+    void testStatusSelection() {
+        final InterceptingOperatorReporterGroup reporterGroup = new InterceptingOperatorReporterGroup();
+
+        final JobStatusMetrics jobStatusReporters =
+                new JobStatusMetrics(0L, enable(ReporterOptions.JobStatusMetrics.STATE));
+        jobStatusReporters.registerReporters(reporterGroup);
+        final Map<JobStatus, StateTimeReporterTest.StatusReporterSet> registeredReporters =
+                extractReporters(reporterGroup);
+
+        for (JobStatus value : JobStatus.values()) {
+            if (value.isTerminalState() || value == JobStatus.RECONCILING) {
+                assertThat(registeredReporters).doesNotContainKey(value);
+            } else {
+                assertThat(registeredReporters).containsKey(value);
+            }
+        }
+    }
+}

